CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE IF NOT EXISTS app_user(user_id BIGSERIAL PRIMARY KEY, full_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role IN ('PATIENT','ADMIN','RECEPTIONIST','BILLING_STAFF')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS patient(patient_id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL UNIQUE REFERENCES app_user(user_id),patient_no TEXT NOT NULL UNIQUE,phone TEXT,date_of_birth DATE,address TEXT);
CREATE TABLE IF NOT EXISTS department(department_id BIGSERIAL PRIMARY KEY,department_name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS doctor(doctor_id BIGSERIAL PRIMARY KEY,full_name TEXT NOT NULL,department_id BIGINT NOT NULL REFERENCES department(department_id),specialization TEXT NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS doctor_availability(availability_id BIGSERIAL PRIMARY KEY,doctor_id BIGINT NOT NULL REFERENCES doctor(doctor_id),day_of_week SMALLINT NOT NULL CHECK(day_of_week BETWEEN 0 AND 6),start_time TIME NOT NULL,end_time TIME NOT NULL,CHECK(end_time>start_time));
CREATE TABLE IF NOT EXISTS appointment(appointment_id BIGSERIAL PRIMARY KEY,patient_id BIGINT NOT NULL REFERENCES patient(patient_id),doctor_id BIGINT NOT NULL REFERENCES doctor(doctor_id),start_at TIMESTAMPTZ NOT NULL,end_at TIMESTAMPTZ NOT NULL,status TEXT NOT NULL DEFAULT 'REQUESTED' CHECK(status IN ('REQUESTED','CONFIRMED','CHECKED_IN','COMPLETED','CANCELLED','REJECTED','NO_SHOW')),reason TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(end_at>start_at));
ALTER TABLE appointment DROP CONSTRAINT IF EXISTS appointment_no_doctor_overlap;
ALTER TABLE appointment ADD CONSTRAINT appointment_no_doctor_overlap EXCLUDE USING gist(doctor_id WITH =,tstzrange(start_at,end_at,'[)') WITH &&) WHERE(status IN ('REQUESTED','CONFIRMED','CHECKED_IN'));
CREATE TABLE IF NOT EXISTS ward(ward_id BIGSERIAL PRIMARY KEY,ward_name TEXT NOT NULL UNIQUE,floor TEXT);
CREATE TABLE IF NOT EXISTS room_type(room_type_id BIGSERIAL PRIMARY KEY,type_name TEXT NOT NULL UNIQUE,default_daily_rate NUMERIC(10,2) NOT NULL CHECK(default_daily_rate>=0));
CREATE TABLE IF NOT EXISTS room(room_id BIGSERIAL PRIMARY KEY,ward_id BIGINT NOT NULL REFERENCES ward(ward_id),room_type_id BIGINT NOT NULL REFERENCES room_type(room_type_id),room_number TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS bed(bed_id BIGSERIAL PRIMARY KEY,room_id BIGINT NOT NULL REFERENCES room(room_id),bed_label TEXT NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(room_id,bed_label));
CREATE TABLE IF NOT EXISTS admission(admission_id BIGSERIAL PRIMARY KEY,admission_no TEXT NOT NULL UNIQUE,patient_id BIGINT NOT NULL REFERENCES patient(patient_id),primary_doctor_id BIGINT REFERENCES doctor(doctor_id),admitted_at TIMESTAMPTZ NOT NULL DEFAULT now(),discharged_at TIMESTAMPTZ,status TEXT NOT NULL DEFAULT 'ADMITTED' CHECK(status IN ('ADMITTED','DISCHARGED')),CHECK(discharged_at IS NULL OR discharged_at>=admitted_at),CHECK((status='ADMITTED' AND discharged_at IS NULL) OR(status='DISCHARGED' AND discharged_at IS NOT NULL)));
CREATE TABLE IF NOT EXISTS bed_allocation(allocation_id BIGSERIAL PRIMARY KEY,admission_id BIGINT NOT NULL REFERENCES admission(admission_id),bed_id BIGINT NOT NULL REFERENCES bed(bed_id),allocated_from TIMESTAMPTZ NOT NULL DEFAULT now(),allocated_until TIMESTAMPTZ,CHECK(allocated_until IS NULL OR allocated_until>allocated_from));
ALTER TABLE bed_allocation DROP CONSTRAINT IF EXISTS bed_allocation_no_overlap;
ALTER TABLE bed_allocation ADD CONSTRAINT bed_allocation_no_overlap EXCLUDE USING gist(bed_id WITH =,tstzrange(allocated_from,allocated_until,'[)') WITH &&) WHERE(allocated_until IS NULL);
CREATE TABLE IF NOT EXISTS invoice(invoice_id BIGSERIAL PRIMARY KEY,invoice_number TEXT NOT NULL UNIQUE,appointment_id BIGINT UNIQUE REFERENCES appointment(appointment_id),admission_id BIGINT UNIQUE REFERENCES admission(admission_id),status TEXT NOT NULL DEFAULT 'ISSUED' CHECK(status IN ('DRAFT','ISSUED','VOID')),issued_at TIMESTAMPTZ NOT NULL DEFAULT now(),created_by_user_id BIGINT REFERENCES app_user(user_id),CHECK(num_nonnulls(appointment_id,admission_id)=1));
CREATE TABLE IF NOT EXISTS invoice_line(invoice_line_id BIGSERIAL PRIMARY KEY,invoice_id BIGINT NOT NULL REFERENCES invoice(invoice_id) ON DELETE CASCADE,description TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price NUMERIC(10,2) NOT NULL CHECK(unit_price>=0));
CREATE TABLE IF NOT EXISTS payment(payment_id BIGSERIAL PRIMARY KEY,invoice_id BIGINT NOT NULL REFERENCES invoice(invoice_id),amount NUMERIC(10,2) NOT NULL CHECK(amount>0),method TEXT NOT NULL CHECK(method IN ('CASH','UPI','CARD','BANK_TRANSFER')),status TEXT NOT NULL DEFAULT 'SUCCESS' CHECK(status IN ('PENDING','SUCCESS','FAILED','REFUNDED')),received_at TIMESTAMPTZ NOT NULL DEFAULT now(),received_by_user_id BIGINT REFERENCES app_user(user_id));
CREATE TABLE IF NOT EXISTS receipt(receipt_id BIGSERIAL PRIMARY KEY,payment_id BIGINT NOT NULL UNIQUE REFERENCES payment(payment_id),receipt_number TEXT NOT NULL UNIQUE,issued_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log(audit_id BIGSERIAL PRIMARY KEY,actor_user_id BIGINT REFERENCES app_user(user_id),action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),details JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX IF NOT EXISTS idx_appointment_patient_start ON appointment(patient_id,start_at DESC);
CREATE INDEX IF NOT EXISTS idx_appointment_doctor_start ON appointment(doctor_id,start_at);
CREATE INDEX IF NOT EXISTS idx_payment_invoice ON payment(invoice_id);
